  function drawClassicExpansionImage(src, x, y, width = TILE, height = TILE) {
    let entry = expansionClassicImages.get(src);
    if (!entry) {
      const img = new Image();
      entry = { img, ready: false, failed: false };
      expansionClassicImages.set(src, entry);
      img.onload = () => { entry.ready = true; };
      img.onerror = () => { entry.failed = true; };
      img.src = src;
    }
    if (!entry.ready || entry.failed) return false;
    ctx.drawImage(entry.img, x, y, width, height);
    return true;
  }
