  function createBgmTrack(src, volume) {
    const track = new Audio(src);
    track.loop = true;
    track.preload = "auto";
    track.volume = volume;
    track.addEventListener("error", () => {
      pushLog(`Music file failed: ${src}`, "bad");
    });
    return track;
  }

  function ensureBgmTracks() {
    if (audio.bgmReady) return;
    audio.bgmNormal = createBgmTrack(MUSIC_TRACKS.normal, 0.36);
    audio.bgmDeep = createBgmTrack(MUSIC_TRACKS.deep, 0.38);
    audio.bgmUltra = createBgmTrack(MUSIC_TRACKS.ultra, 0.4);
    audio.bgmOtter = createBgmTrack(MUSIC_TRACKS.otter, 0.4);
    audio.bgmCamp = createBgmTrack(MUSIC_TRACKS.camp, 0.34);
    audio.bgmCampLastLife = createBgmTrack(MUSIC_TRACKS.campLastLife, 0.34);
    audio.bgmBoss = createBgmTrack(MUSIC_TRACKS.boss, 0.4);
    audio.bgmBossDeep = createBgmTrack(MUSIC_TRACKS.bossDeep, 0.4);
    audio.bgmBossUltra = createBgmTrack(MUSIC_TRACKS.bossUltra, 0.42);
    audio.bgmNormal.load();
    audio.bgmDeep.load();
    audio.bgmUltra.load();
    audio.bgmOtter.load();
    audio.bgmCamp.load();
    audio.bgmCampLastLife.load();
    audio.bgmBoss.load();
    audio.bgmBossDeep.load();
    audio.bgmBossUltra.load();
    audio.bgmReady = true;
  }

  function pauseBgmTrack(track, resetTime = false) {
    if (!track) return;
    track.pause();
    if (resetTime) {
      track.currentTime = 0;
    }
  }

  function stopAllBgm(resetTime = false) {
    pauseBgmTrack(audio.bgmNormal, resetTime);
    pauseBgmTrack(audio.bgmDeep, resetTime);
    pauseBgmTrack(audio.bgmUltra, resetTime);
    pauseBgmTrack(audio.bgmOtter, resetTime);
    pauseBgmTrack(audio.bgmCamp, resetTime);
    pauseBgmTrack(audio.bgmCampLastLife, resetTime);
    pauseBgmTrack(audio.bgmBoss, resetTime);
    pauseBgmTrack(audio.bgmBossDeep, resetTime);
    pauseBgmTrack(audio.bgmBossUltra, resetTime);
    audio.currentBgm = null;
  }

  function playBgmTrack(track) {
    if (!track || state.audioMuted) return;
    const playPromise = track.play();
    if (playPromise && typeof playPromise.catch === "function") {
      playPromise.catch(() => {
        if (!audio.bgmWarned) {
          pushLog("Browser blocked autoplay. Press any key or click game area.", "bad");
          audio.bgmWarned = true;
        }
      });
    }
  }

  function syncBgmWithState(force = false) {
    if (isSimulationActive() && state.simulation.suppressAudio) {
      stopAllBgm(false);
      stopSplashTrack(false);
      stopDeathTrack(false);
      stopVictoryTrack(false);
      stopFinalGameOverTrack(false);
      return;
    }
    ensureBgmTracks();

    const allowMusic = state.phase === "playing" || state.phase === "relic" || state.phase === "camp";
    const splashPlaying = state.phase === "menu" || state.phase === "dead";
    if (state.audioMuted || !allowMusic) {
      stopAllBgm(false);
      if (!splashPlaying) {
        stopSplashTrack(false);
      }
      return;
    }

    stopSplashTrack(false);

    const ultraTheme = state.depth >= ULTRA_THEME_START_DEPTH;
    const deepTheme = state.depth >= DEEP_THEME_START_DEPTH;
    const otterTheme = state.roomType === "otter" && !state.bossRoom;
    const target = state.phase === "camp"
      ? ((state.lives <= 1 && audio.bgmCampLastLife) ? audio.bgmCampLastLife : audio.bgmCamp)
      : state.bossRoom
        ? ultraTheme
          ? (audio.bgmBossUltra || audio.bgmBossDeep || audio.bgmBoss)
          : (deepTheme ? (audio.bgmBossDeep || audio.bgmBoss) : audio.bgmBoss)
        : otterTheme
          ? (audio.bgmOtter || (ultraTheme ? (audio.bgmUltra || audio.bgmDeep || audio.bgmNormal) : deepTheme ? audio.bgmDeep : audio.bgmNormal))
        : ultraTheme
          ? (audio.bgmUltra || audio.bgmDeep || audio.bgmNormal)
          : deepTheme
            ? audio.bgmDeep
          : audio.bgmNormal;
    const allTracks = [
      audio.bgmNormal,
      audio.bgmDeep,
      audio.bgmUltra,
      audio.bgmOtter,
      audio.bgmCamp,
      audio.bgmCampLastLife,
      audio.bgmBoss,
      audio.bgmBossDeep,
      audio.bgmBossUltra
    ];
    for (const track of allTracks) {
      if (!track || track === target) continue;
      pauseBgmTrack(track, true);
    }

    if (audio.currentBgm !== target) {
      pauseBgmTrack(audio.currentBgm, true);
      audio.currentBgm = target;
    }

    if (force && target.paused) {
      target.currentTime = 0;
    }
    if (target.paused) {
      playBgmTrack(target);
    }
  }

  function playTone(ctx, destination, options) {
    const {
      at = ctx.currentTime,
      frequency = 220,
      endFrequency = frequency,
      duration = 0.08,
      type = "square",
      gain = 0.08
    } = options;
    const osc = ctx.createOscillator();
    const env = ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(frequency, at);
    osc.frequency.linearRampToValueAtTime(endFrequency, at + duration);
    env.gain.setValueAtTime(0.0001, at);
    env.gain.linearRampToValueAtTime(gain, at + 0.01);
    env.gain.exponentialRampToValueAtTime(0.0001, at + duration);
    osc.connect(env);
    env.connect(destination);
    osc.start(at);
    osc.stop(at + duration + 0.02);
  }

  function playSfx(kind) {
    if (isSimulationActive() && state.simulation.suppressAudio) return;
    if (!ensureAudio()) return;
    const ctx = audio.ctx;
    const out = audio.master;
    const now = ctx.currentTime + 0.002;

    if (kind === "hit") {
      playTone(ctx, out, {
        at: now,
        frequency: 170,
        endFrequency: 120,
        duration: 0.06,
        type: "square",
        gain: 0.06
      });
      return;
    }
    if (kind === "crit") {
      playTone(ctx, out, {
        at: now,
        frequency: 280,
        endFrequency: 520,
        duration: 0.08,
        type: "square",
        gain: 0.07
      });
      playTone(ctx, out, {
        at: now + 0.06,
        frequency: 620,
        endFrequency: 880,
        duration: 0.1,
        type: "triangle",
        gain: 0.06
      });
      return;
    }
    if (kind === "death") {
      playTone(ctx, out, {
        at: now,
        frequency: 210,
        endFrequency: 90,
        duration: 0.24,
        type: "sawtooth",
        gain: 0.08
      });
      playTone(ctx, out, {
        at: now + 0.12,
        frequency: 90,
        endFrequency: 60,
        duration: 0.2,
        type: "triangle",
        gain: 0.06
      });
      return;
    }
    if (kind === "chrono") {
      playTone(ctx, out, {
        at: now,
        frequency: 170,
        endFrequency: 620,
        duration: 0.18,
        type: "triangle",
        gain: 0.08
      });
      playTone(ctx, out, {
        at: now + 0.04,
        frequency: 250,
        endFrequency: 1040,
        duration: 0.24,
        type: "sawtooth",
        gain: 0.06
      });
      playTone(ctx, out, {
        at: now + 0.16,
        frequency: 940,
        endFrequency: 420,
        duration: 0.28,
        type: "sine",
        gain: 0.055
      });
      return;
    }
    if (kind === "bosswarn") {
      playTone(ctx, out, {
        at: now,
        frequency: 150,
        endFrequency: 300,
        duration: 0.18,
        type: "sawtooth",
        gain: 0.085
      });
      playTone(ctx, out, {
        at: now + 0.16,
        frequency: 300,
        endFrequency: 120,
        duration: 0.34,
        type: "triangle",
        gain: 0.07
      });
      return;
    }
    if (kind === "portal") {
      playTone(ctx, out, {
        at: now,
        frequency: 280,
        endFrequency: 540,
        duration: 0.12,
        type: "triangle",
        gain: 0.065
      });
      playTone(ctx, out, {
        at: now + 0.09,
        frequency: 510,
        endFrequency: 760,
        duration: 0.14,
        type: "triangle",
        gain: 0.06
      });
      return;
    }
    if (kind === "shrine") {
      playTone(ctx, out, {
        at: now,
        frequency: 360,
        endFrequency: 560,
        duration: 0.12,
        type: "triangle",
        gain: 0.06
      });
      playTone(ctx, out, {
        at: now + 0.08,
        frequency: 520,
        endFrequency: 760,
        duration: 0.14,
        type: "sine",
        gain: 0.05
      });
      return;
    }
    if (kind === "chest") {
      playTone(ctx, out, {
        at: now,
        frequency: 620,
        endFrequency: 730,
        duration: 0.06,
        type: "square",
        gain: 0.06
      });
      playTone(ctx, out, {
        at: now + 0.05,
        frequency: 760,
        endFrequency: 880,
        duration: 0.08,
        type: "square",
        gain: 0.06
      });
    }
  }

  function toggleAudio() {
    state.audioMuted = !state.audioMuted;
    setStorageItem(STORAGE_AUDIO_MUTED, state.audioMuted ? "1" : "0");
    if (state.audioMuted) {
      stopSplashTrack(false);
      stopDeathTrack(false);
      stopVictoryTrack(false);
      stopFinalGameOverTrack(false);
    }
    syncBgmWithState(true);
    pushLog(`Audio ${state.audioMuted ? "muted" : "enabled"}.`);
    markUiDirty();
  }

  function toggleDebugAiOverlay() {
    state.debugAiOverlay = !state.debugAiOverlay;
    setStorageItem(STORAGE_DEBUG_AI_OVERLAY, state.debugAiOverlay ? "1" : "0");
    pushLog(`AI debug overlay ${state.debugAiOverlay ? "ON" : "OFF"} (${DEBUG_AI_OVERLAY_TOGGLE_KEY.toUpperCase()}).`);
    markUiDirty();
  }

  function getEnemySpeedLabel(mode = state.enemySpeedMode) {
    const normalized = sanitizeEnemySpeedMode(mode);
    if (normalized === "slow") return "Slow";
    if (normalized === "fast") return "Fast";
    return "Standard";
  }

  function getEnemyTurnStepDelayMs() {
    const mode = sanitizeEnemySpeedMode(state.enemySpeedMode);
    const multiplier = Number(ENEMY_TURN_DELAY_MULTIPLIERS[mode]) || 1;
    return Math.max(20, Math.round(ENEMY_TURN_STEP_DELAY_BASE_MS * multiplier));
  }

  function setEnemySpeedMode(mode, options = {}) {
    const normalized = sanitizeEnemySpeedMode(mode);
    if (normalized === state.enemySpeedMode) return false;
    state.enemySpeedMode = normalized;
    setStorageItem(STORAGE_ENEMY_SPEED, normalized);
    if (!options.silent) {
      pushLog(`Enemy speed: ${getEnemySpeedLabel(normalized)}.`);
    }
    markUiDirty();
    return true;
  }

  function shiftEnemySpeedMode(step) {
    const current = sanitizeEnemySpeedMode(state.enemySpeedMode);
    const index = ENEMY_SPEED_MODES.indexOf(current);
    const nextIndex = (index + step + ENEMY_SPEED_MODES.length) % ENEMY_SPEED_MODES.length;
    setEnemySpeedMode(ENEMY_SPEED_MODES[nextIndex], { silent: true });
  }

  function getEnemySpeedOptionsItems() {
    return [
      { id: "slow", key: "1", label: "Slow" },
      { id: "standard", key: "2", label: "Standard" },
      { id: "fast", key: "3", label: "Fast" }
    ];
  }

  function getAudioOptionsItems() {
    return [
      { id: "on", key: "1", label: "On" },
      { id: "off", key: "2", label: "Off" }
    ];
  }


  function getTutorialOptionsItems() {
    return [
      { id: "run", key: "1", label: "How To Play" },
      { id: "camp", key: "2", label: "Camp Guide" },
      { id: "merchant", key: "3", label: "Merchant Guide" },
      { id: "combat_basics", key: "4", label: "Combat Basics" },
      { id: "status_effects", key: "5", label: "Status Effects" },
      { id: "skills_deep_dive", key: "6", label: "Skills Deep Dive" },
      { id: "economy_survival", key: "7", label: "Economy & Survival" },
      { id: "enemy_threats", key: "8", label: "Enemy Threat Guide" }
    ];
  }

  function getMenuOptionsRootItems() {
    return [
      {
        id: "enemy_speed",
        key: "1",
        title: "Enemy Speed",
        desc: `Current: ${getEnemySpeedLabel()} (${getEnemyTurnStepDelayMs()} ms per enemy step).`
      },
      {
        id: "audio",
        key: "2",
        title: "Audio",
        desc: `Current: ${state.audioMuted ? "Off" : "On"}.`
      }
    ];
  }

  function getActiveMenuOptionsItems() {
    if (state.menuOptionsView === "enemy_speed") {
      return getEnemySpeedOptionsItems();
    }
    if (state.menuOptionsView === "audio") {
      return getAudioOptionsItems();
    }

    if (state.menuOptionsView === "tutorial") {
      return getTutorialOptionsItems();
    }
    return getMenuOptionsRootItems();
  }

  function syncMenuOptionsIndex() {
    const items = getActiveMenuOptionsItems();
    if (!items.length) {
      state.menuOptionsIndex = 0;
      return;
    }
    state.menuOptionsIndex = clamp(state.menuOptionsIndex, 0, items.length - 1);
  }

  function moveMenuOptionsSelection(step) {
    const items = getActiveMenuOptionsItems();
    if (!items.length) return;
    const len = items.length;
    state.menuOptionsIndex = (state.menuOptionsIndex + step + len) % len;
    markUiDirty();
  }

  function openEnemySpeedOptions() {
    state.menuOptionsView = "enemy_speed";
    const idx = ENEMY_SPEED_MODES.indexOf(sanitizeEnemySpeedMode(state.enemySpeedMode));
    state.menuOptionsIndex = idx >= 0 ? idx : 1;
    markUiDirty();
  }

  function openAudioOptions() {
    state.menuOptionsView = "audio";
    state.menuOptionsIndex = state.audioMuted ? 1 : 0;
    markUiDirty();
  }


  function openTutorialOptions() {
    state.menuOptionsView = "tutorial";
    state.menuOptionsIndex = 0;
    markUiDirty();
  }

  function openTutorialMenu() {
    state.menuOptionsOpen = true;
    state.menuOptionsContext = "tutorial";
    state.menuOptionsView = "tutorial";
    state.menuOptionsIndex = 0;
    markUiDirty();
  }

  function backFromMenuOptionsView() {
    if (state.menuOptionsView === "enemy_speed") {
      state.menuOptionsView = "root";
      state.menuOptionsIndex = 0;
      markUiDirty();
      return true;
    }
    if (state.menuOptionsView === "audio") {
      state.menuOptionsView = "root";
      state.menuOptionsIndex = 0;
      markUiDirty();
      return true;
    }

    if (state.menuOptionsView === "tutorial") {
      if (state.menuOptionsContext === "options") {
        state.menuOptionsView = "root";
        state.menuOptionsIndex = 0;
        markUiDirty();
        return true;
      }
      return false;
    }
    return false;
  }

  function activateMenuOptionsSelection(index = state.menuOptionsIndex) {
    const items = getActiveMenuOptionsItems();
    if (!items.length) return;
    const item = items[clamp(index, 0, items.length - 1)];
    if (!item) return;

    if (state.menuOptionsView === "root") {
      if (item.id === "enemy_speed") {
        openEnemySpeedOptions();
      } else if (item.id === "audio") {
        openAudioOptions();
      }
      return;
    }
    if (state.menuOptionsView === "enemy_speed") {
      setEnemySpeedMode(item.id, { silent: true });
      const idx = ENEMY_SPEED_MODES.indexOf(sanitizeEnemySpeedMode(state.enemySpeedMode));
      state.menuOptionsIndex = idx >= 0 ? idx : 1;
      markUiDirty();
      return;
    }
    if (state.menuOptionsView === "audio") {
      if (item.id === "on" && state.audioMuted) {
        toggleAudio();
      } else if (item.id === "off" && !state.audioMuted) {
        toggleAudio();
      }
      state.menuOptionsIndex = state.audioMuted ? 1 : 0;
      markUiDirty();
      return;
    }

    if (state.menuOptionsView === "tutorial") {
      closeMenuOptions();
      openTutorialModal(item.id, "manual");
    }
  }

  function openMenuOptions() {
    state.menuOptionsOpen = true;
    state.menuOptionsContext = "options";
    state.menuOptionsView = "root";
    state.menuOptionsIndex = 0;
    markUiDirty();
  }

  function closeMenuOptions() {
    if (!state.menuOptionsOpen) return;
    state.menuOptionsOpen = false;
    state.menuOptionsContext = "options";
    state.menuOptionsView = "root";
    state.menuOptionsIndex = 0;
    markUiDirty();
  }

  function getTutorialKindForHotkeyContext() {
    if (state.phase === "camp") return "camp";
    if (state.phase === "playing" && state.merchantMenuOpen) return "merchant";
    return "run";
  }

  function canOpenTutorialModal() {
    if (state.phase === "boot" || state.phase === "splash") return false;
    if (state.nameModalOpen) return false;
    if (state.leaderboardModalOpen && state.phase === "menu") return false;
    if (state.phase === "menu" && state.menuNewGameConfirmOpen) return false;
    if (state.phase === "menu" && state.menuOptionsOpen) return false;
    if (canUseDebugCheats() && state.debugCheatOpen) return false;
    if (state.phase === "playing" && state.extractConfirm) return false;
    if (state.phase === "camp" && state.extractRelicPrompt) return false;
    if (state.phase === "camp" && state.campStartDepthPromptOpen) return false;
    if (state.phase === "dead" && state.finalGameOverPrompt) return false;
    if (state.phase === "won" && state.finalVictoryPrompt) return false;
    return true;
  }

  function markTutorialSeen(kind) {
    if (kind === "run") {
      if (state.tutorialRunSeen) return;
      state.tutorialRunSeen = true;
      setStorageItem(STORAGE_TUTORIAL_RUN_SEEN, "1");
      return;
    }
    if (kind === "camp") {
      if (state.tutorialCampSeen) return;
      state.tutorialCampSeen = true;
      setStorageItem(STORAGE_TUTORIAL_CAMP_SEEN, "1");
      return;
    }
    if (kind === "merchant") {
      if (state.tutorialMerchantSeen) return;
      state.tutorialMerchantSeen = true;
      setStorageItem(STORAGE_TUTORIAL_MERCHANT_SEEN, "1");
      return;
    }
    if (kind === "portal") {
      if (state.tutorialPortalSeen) return;
      state.tutorialPortalSeen = true;
      setStorageItem(STORAGE_TUTORIAL_PORTAL_SEEN, "1");
    }
  }

  function openTutorialModal(kind, source = "manual") {
    const allowedKinds = new Set([
      "run",
      "camp",
      "merchant",
      "portal",
      "combat_basics",
      "status_effects",
      "skills_deep_dive",
      "economy_survival",
      "enemy_threats"
    ]);
    const normalizedKind = allowedKinds.has(kind) ? kind : "run";
    if (state.tutorialModalOpen) return false;
    if (!canOpenTutorialModal()) return false;
    state.tutorialModalOpen = true;
    state.tutorialModalKind = normalizedKind;
    state.tutorialModalSource = source === "auto" ? "auto" : "manual";
    markTutorialSeen(
      normalizedKind === "camp" || normalizedKind === "merchant" || normalizedKind === "portal"
        ? normalizedKind
        : "run"
    );
    markUiDirty();
    return true;
  }

  function canCycleTutorialModalPagesFromMenu() {
    return (
      state.tutorialModalOpen &&
      state.phase === "menu" &&
      state.tutorialModalSource === "manual"
    );
  }

  function cycleTutorialModalPage(step) {
    if (!canCycleTutorialModalPagesFromMenu()) return false;
    const items = getTutorialOptionsItems();
    if (!items.length) return false;
    const currentId = state.tutorialModalKind;
    const currentIndex = items.findIndex((item) => item.id === currentId);
    if (currentIndex < 0) return false;
    const nextIndex = currentIndex + step;
    if (nextIndex < 0 || nextIndex >= items.length) return false;
    const nextItem = items[nextIndex];
    if (!nextItem) return false;
    state.tutorialModalKind = nextItem.id;
    markTutorialSeen(
      nextItem.id === "camp"
        ? "camp"
        : nextItem.id === "merchant"
          ? "merchant"
          : "run"
    );
    markUiDirty();
    return true;
  }

  function closeTutorialModal(options = {}) {
    if (!state.tutorialModalOpen) return false;
    const reopenTutorialMenu = Boolean(options.reopenTutorialMenu);
    state.tutorialModalOpen = false;
    state.tutorialModalKind = null;
    state.tutorialModalSource = null;
    if (reopenTutorialMenu && state.phase === "menu") {
      openTutorialMenu();
      return true;
    }
    markUiDirty();
    return true;
  }

  function scheduleCampTutorialIfNeeded() {
    if (isSimulationActive()) return;
    if (state.phase !== "camp") return;
    if (state.tutorialCampSeen) return;
    state.tutorialCampAutoPending = true;
  }

  function tryOpenPendingTutorialModal() {
    if (isSimulationActive()) return false;
    if (state.phase !== "camp") {
      state.tutorialCampAutoPending = false;
      return false;
    }
    if (!state.tutorialCampSeen && !state.tutorialCampAutoPending) {
      state.tutorialCampAutoPending = true;
    }
    if (!state.tutorialCampAutoPending) return false;
    if (state.tutorialCampSeen) {
      state.tutorialCampAutoPending = false;
      return false;
    }
    if (state.tutorialModalOpen) return false;
    if (state.extractRelicPrompt || state.campStartDepthPromptOpen) return false;
    if (!openTutorialModal("camp", "auto")) return false;
    state.tutorialCampAutoPending = false;
    return true;
  }

  function tryOpenFirstPortalTutorialIfNeeded() {
    if (state.phase !== "playing") return false;
    if (state.tutorialPortalSeen) return false;
    if (state.depth !== 0) return false;
    if (!state.roomCleared) return false;
    if (!isOnPortal()) return false;
    if (state.tutorialModalOpen) return false;
    return openTutorialModal("portal", "auto");
  }

